<script setup>import{Head,Link,useForm}from'@inertiajs/vue3';import AppLayout from'../../../Layouts/AppLayout.vue';const p=defineProps({assignment:Object,canSubmit:Boolean,blockedReason:String,fileConfig:Object});const form=useForm({text_content:'',files:[]});const submit=()=>form.post(`/assignments/${p.assignment.id}/submissions`,{forceFormData:true});const label=s=>({SUBMITTED:'ارسال‌شده',UNDER_REVIEW:'در حال بررسی',APPROVED:'تأیید شده',REVISION_REQUESTED:'نیاز به اصلاح',REJECTED:'رد شده'}[s]||s);const size=n=>`${(n/1048576).toFixed(1)} مگابایت`;</script>
<template><AppLayout><Head :title="assignment.title"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><Link :href="`/student/courses/${assignment.lesson.course.id}/lessons/${assignment.lesson.id}`" class="text-teal-700">بازگشت به درس</Link><h1 class="mt-3 text-xl font-bold">{{assignment.title}}</h1><p class="mt-3 whitespace-pre-line">{{assignment.description}}</p><div class="mt-4 text-sm"><p v-if="assignment.due_at">مهلت: {{new Date(assignment.due_at).toLocaleString('fa-IR')}}</p><p>{{assignment.allow_late_submission?'ارسال با تأخیر مجاز است':'ارسال پس از مهلت مجاز نیست'}}</p><p>{{assignment.allow_resubmission?'ارسال مجدد مجاز است':'فقط یک تلاش مجاز است'}}</p><p v-if="assignment.max_attempts">حداکثر {{assignment.max_attempts}} تلاش</p></div></section><section v-if="canSubmit" class="rounded-2xl border bg-white p-5"><h2 class="font-bold">ارسال تلاش جدید</h2><form class="mt-4 space-y-3" @submit.prevent="submit"><textarea v-model="form.text_content" rows="5" class="w-full rounded-xl border p-3" placeholder="توضیحات"></textarea><input type="file" multiple @change="form.files=[...$event.target.files]"><div v-for="(f,i) in form.files" :key="i" class="flex justify-between rounded bg-slate-50 p-2"><span>{{f.name}} — {{size(f.size)}}</span><button type="button" @click="form.files.splice(i,1)">حذف</button></div><p class="text-red-600">{{form.errors.text_content||form.errors.files}}</p><button :disabled="form.processing" class="rounded-xl bg-teal-700 px-4 py-2 text-white">{{form.processing?'در حال ارسال…':'ثبت تکلیف'}}</button></form></section><p v-else class="rounded-xl bg-amber-50 p-4">{{blockedReason}}</p><section class="rounded-2xl border bg-white p-5"><h2 class="font-bold">تاریخچه تلاش‌ها</h2><article v-for="s in assignment.submissions" :key="s.id" class="mt-3 rounded-xl border p-4"><div class="flex justify-between"><strong>تلاش {{s.attempt_number}}</strong><span>{{label(s.status)}}</span></div><p class="mt-2 whitespace-pre-line">{{s.text_content}}</p><p v-if="s.is_late" class="text-red-700">ارسال با تأخیر</p><p v-if="s.reviewer_feedback" class="mt-2 bg-slate-50 p-2">بازخورد: {{s.reviewer_feedback}}</p><a v-for="f in s.files" :href="`/submission-files/${f.id}`" class="block text-teal-700">{{f.original_name}} — {{size(f.file_size)}}</a></article><p v-if="!assignment.submissions.length">هنوز ارسالی ثبت نشده است.</p></section></div></AppLayout></template>
